// src/components/FilmCard.jsx
import React from 'react';

const FilmCard = ({ film }) => {
  // Шлях до зображення має бути відносно папки `public` або імпортуватися
  // Тут використовується простий шлях, як ви вказали у даних:
  const imagePath = film.image; 

  return (
    <div className="film-card">
      <div className="film-card-thumb">
        {/* Припускаємо, що ваші зображення знаходяться в папці `public/films_photo` */}
        <img 
          src={imagePath} // або безпосередньо /films_photo/...
          alt={film.name} 
          className="film-card-img" 
          onError={(e) => { e.target.onerror = null; e.target.src="/path/to/placeholder.jpg" }} // Запобігає помилкам, якщо зображення відсутнє
        />
      </div>
      
      <h4 className="film-card-h4">{film.name}</h4>
      <p>Length: **{film.time} min**</p>
      <p>IMDb Rating: **{film.IMDb_rating}**</p>
      <p>Reviews: {film.number_reviews.toLocaleString()}</p>
    </div>
  );
};

export default FilmCard;
